package org.openenglish.reader;import java.util.concurrent.atomic.AtomicInteger;public class LocalNative {public static volatile float probability=.05f;public static volatile java.util.concurrent.CountDownLatch entered,resume;public static final AtomicInteger closed=new AtomicInteger();public static long vadOpen(String model){return 1;}public static float vadProbability(long id,float[] p){if(entered!=null){entered.countDown();try{resume.await(2,java.util.concurrent.TimeUnit.SECONDS);}catch(InterruptedException e){throw new RuntimeException(e);}}return probability;}public static void vadReset(long id){}public static void vadClose(long id){closed.incrementAndGet();}}
